mapper.insert:
INSERT INTO T_NEWS_QUIZ (
       QUIZ_DATE
      ,QUESTIONS_JSON
      ,NEWS_COUNT
) VALUES (
       #{quizDate}
      ,#{questionsJson}
      ,#{newsCount}
)
ON CONFLICT (QUIZ_DATE) DO NOTHING

mapper.select:
SELECT  SCORE           AS "score"
       ,ANSWERS_JSON    AS "answersJson"
  FROM T_NEWS_QUIZ_PLAY
 WHERE 1=1
   AND QUIZ_DATE = #{quizDate}
   AND USER_ID   = #{userId}

mapper.insert:
INSERT INTO T_NEWS_QUIZ_PLAY (
       QUIZ_DATE
      ,USER_ID
      ,SCORE
      ,ANSWERS_JSON
) VALUES (
       #{quizDate}
      ,#{userId}
      ,#{score}
      ,#{answersJson}
)
ON CONFLICT (QUIZ_DATE, USER_ID) DO NOTHING
